/* Additive teaching edition. f2-l*-p/t IDs and their historical meaning stay intact. */
(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory(require('./foundation'),require('./scenarios'));else root.CourseMethod=factory(root.Foundation,root.CourseScenarios);})(globalThis,function(F,S){
  'use strict';
  const edition='method1',packets=[];
  const q=(prompt,answer,refs,explanation,extra={})=>({type:'text',prompt,answers:Array.isArray(answer)?answer:[answer],refs:refs.split(','),explanation,skill:'writing',...extra});
  function add(day,outcome,focus,error,correction,reason,pool,task,model,checks){
    packets.push({day,outcome,focus,error,correction,reason,pool,task,model,checks,
      sessions:[['Hiểu và thử','Nhớ lại điều cũ, làm theo mẫu, rồi che mẫu và tự thử. Có thể dừng giữa bài.'],['Đổi tình huống','Dùng điều vừa học với thông tin khác. Sau câu sai, đọc cách sửa rồi tự làm lượt mới.'],['Quay lại nhớ','Sau lượt vận dụng đạt, thử lại ở mốc 1/3/7 ngày. Mỗi mốc chỉ là một mẫu nhỏ, không chứng nhận đã biết hết.']]});
  }
  for(let day=1;day<=4;day++){
    const l=F.lessons[day-1],letters=F.alphabet.filter(a=>l.letters.includes(a.letter));
    const pool=letters.flatMap(a=>[q(`Viết dạng thường của ${a.letter}.`,a.lower,`${day}:letter`,`${a.letter} và ${a.lower} cùng một chữ.`,{caseSensitive:true,skill:'letters'}),q('Nghe tên chữ và tự nhập; chưa mở văn bản.',a.letter,`${day}:names`,`Bạn nghe tên chữ ${a.letter} ${a.ipa}.`,{audio:a.audio,skill:'listening'})]);
    add(day,`Nhận dạng và nghe từng chữ ${l.title}, biết chữ nào mình còn nhầm.`,`Tách hai việc: nhìn hình để ghép hoa–thường; nghe tên để viết lại. Không nhìn chữ khi làm câu nghe. Tên chữ không thay âm trong từ.`,`${letters[0].letter} và ${letters[0].lower} là hai chữ khác nhau.`,`${letters[0].letter} và ${letters[0].lower} cùng tên; chỉ khác hình viết.`,'Đọc tên rồi tự viết; dùng thẻ kiểm tra sau khi đã thử. Nếu phải mở hỗ trợ, lượt đó không là bằng chứng nghe độc lập.',pool,'Chọn hai chữ khó nhất. Viết ra giấy, nghe lại và tự đánh dấu chỗ nhầm. Sau đó nhờ người khác chọn bất kỳ ba thẻ để bạn gọi tên.',letters.map(a=>`${a.letter}–${a.lower}`).join(' · '),['Tôi thử trước khi xem.','Tôi phân biệt nhìn chữ với nghe tên.','Tôi ghi lại chữ cần quay lại.']);
  }
  add(5,'Phân biệt cặp dễ nhầm mà không dựa vào vị trí đáp án.','Nghe riêng từng chữ rồi đổi thứ tự. Với b/d, nhìn phía của nét cao. Với G/J, nghe phần cuối tên.', 'Nghe G nhưng viết J.','G /dʒiː/ khác J /dʒeɪ/.','Cùng âm đầu chưa đủ; cần nghe cả tên.',[
    q('Nghe và nhập chữ.', 'P','5:pairs','P /piː/, khác B /biː/.',{audio:{kind:'letter',text:'P'},skill:'listening'}),q('Viết dạng thường của B.','b','5:forms','B → b; nét cao bên trái.',{caseSensitive:true,skill:'letters'}),q('Nghe và nhập chữ.','E','5:pairs','E /iː/, khác I /aɪ/.',{audio:{kind:'letter',text:'E'},skill:'listening'}),q('Viết dạng thường của D.','d','5:forms','D → d; nét cao bên phải.',{caseSensitive:true,skill:'letters'}),q('Nghe và nhập chữ.','M','5:mn','M khép hai môi ở cuối tên.',{audio:{kind:'letter',text:'M'},skill:'listening'}),q('Nghe và nhập chữ.','J','5:pairs','J có phần cuối /eɪ/.',{audio:{kind:'letter',text:'J'},skill:'listening'})
  ],'Tự chọn B/D, E/I hoặc G/J. Nghe mỗi chữ hai lượt với thứ tự khác nhau; viết rồi đối chiếu.','B → b; D → d. G khác J.',['Tôi nghe hết tên.','Tôi không mở chữ trước khi đoán.']);
  add(6,'Đánh vần được một tên khác tên mẫu LAN và nhận ra chữ được đọc rời.','Đọc cả tên và đánh vần là hai nhiệm vụ. Viết tên không dấu, tách từng chữ; nghe từng thẻ, che rồi nói lại.','Đánh vần MAI thành M–I–A.','MAI là M–A–I.','Giữ đúng thứ tự chữ; tốc độ chưa quan trọng.',[
    q('Ghép tên từ M–A–I (nhập liền).','Mai','6:spell','M rồi A rồi I.',{skill:'letters'}),q('Ghép tên từ A–N (nhập liền).','An','6:spell','A rồi N.',{skill:'letters'}),q('Nhập ba chữ của LAN liền nhau.','LAN','6:spell','L–A–N.',{skill:'letters'}),q('Nghe và nhập chữ.','Q','3:names','Q là /kjuː/.',{audio:{kind:'letter',text:'Q'},skill:'listening'}),q('Nghe và nhập chữ.','Y','4:names','Y là /waɪ/.',{audio:{kind:'letter',text:'Y'},skill:'listening'}),q('Nghe và nhập chữ.','X','4:names','X là /ɛks/.',{audio:{kind:'letter',text:'X'},skill:'listening'})
  ],'Viết tên của bạn hoặc MAI. Đánh vần không nhìn. Đổi vai: người nghe viết lại, hai người đối chiếu.','MAI → M–A–I.',['Tôi giữ thứ tự.','Người nghe viết lại được hoặc tôi biết chữ nào cần nhắc lại.']);
  add(7,'Chọn đúng cách đọc cả từ hoặc đánh vần khi mục đích thay đổi.','Khi cần biết cách viết, dùng tên chữ. Khi gọi đồ vật, nghe và đọc cả từ. Không ghép tên chữ thành phát âm của từ.','Đọc cat bằng tên C–A–T khi muốn nói con mèo.','Nghe cat và đọc cả từ; C–A–T chỉ là đánh vần.','Chọn nhiệm vụ trước khi luyện.',[
    q('Bạn được đánh vần A–P–P–L–E. Viết lại từ.','apple','7:whole','Năm chữ tạo thành apple.'),q('Viết từ tiếng Anh chỉ con mèo, không ghi tên từng chữ.','cat','7:word:cat','cat là cả từ con mèo.'),q('Nghe rồi viết cả từ.','egg','7:word:egg','egg nghĩa là quả trứng.',{audio:{kind:'word',text:'egg'},skill:'listening'}),q('C–A–T tạo thành từ gì?','cat','7:whole','Giữ đúng thứ tự.'),q('Viết từ nghĩa là quả táo.','apple','7:word:apple','apple là quả táo.'),q('Nghe và viết cả từ.','cat','7:whole','Nghe âm trong từ, không tên chữ.',{audio:{kind:'word',text:'cat'},skill:'listening'})
  ],'Chọn apple. Nói cả từ rồi đánh vần. Ghi chú hai việc nghe khác nhau ra sao.','apple; A–P–P–L–E.',['Tôi không nối tên chữ để đoán âm.','Tôi biết mình đang luyện việc nào.']);
  add(8,'Nghe và gọi được từ thuộc hai nhóm âm đã dạy.','Chỉ đổi độ mở miệng và vị trí lưỡi; nghe cat/bag rồi pen/egg. Thu âm từng cặp để so sánh, không tự cho điểm chuẩn.','Dùng tên A /eɪ/ để đọc cat.','Nghe cả từ cat /kæt/.','Tên chữ và âm giữa từ khác nhau.',[
    q('Không nhìn thẻ: viết từ nghĩa là cái túi.','bag','8:word:bag','bag có /æ/.',{skill:'vocabulary'}),q('Nghe rồi viết từ.','pen','8:word:pen','pen có /ɛ/.',{audio:{kind:'word',text:'pen'},skill:'listening'}),q('Viết từ nghĩa là quả trứng.','egg','8:word:egg','egg có /ɛ/.'),q('Nghe và nhập từ.','bag','8:word:bag','bag có âm giữa /æ/.',{audio:{kind:'word',text:'bag'},skill:'listening'}),q('Viết từ nghĩa là con mèo.','cat','8:word:cat','cat có /æ/.'),q('Nghe và nhập từ.','egg','8:word:egg','egg bắt đầu /ɛ/.',{audio:{kind:'word',text:'egg'},skill:'listening'})
  ],'Ghi hai lượt cat–pen. Lượt đầu nhìn mẫu; lượt sau che chữ. Ghi một điểm khác bạn nghe được hoặc chưa chắc.','cat → miệng mở rộng hơn; pen → mở vừa.',['Tôi nghe trước khi thu.','Tôi so cả từ, không đọc IPA bằng TTS.']);
  add(9,'Phân biệt ship/sheep, sit/seat khi không có lựa chọn gợi ý.','Giữ âm đầu/cuối, đổi chất âm giữa: /ɪ/ thả lỏng, /iː/ lưỡi trước cao hơn. Kéo dài âm sai không tự biến thành âm đúng.','Nói ship dài hơn rồi coi đó là sheep.','So vị trí lưỡi và chất âm, nghe mẫu từng từ.','Hai từ khác nghĩa nên việc giữ chất âm có ích.',[
    q('Nghe rồi tự viết từ.','sheep','9:word:sheep','sheep là con cừu.',{audio:{kind:'word',text:'sheep'},skill:'listening'}),q('Viết từ nghĩa là chỗ ngồi.','seat','9:word:seat','seat, khác sit là ngồi.'),q('Nghe và nhập từ.','ship','9:word:ship','ship là tàu thủy.',{audio:{kind:'word',text:'ship'},skill:'listening'}),q('Viết từ nghĩa là ngồi.','sit','9:word:sit','sit có /ɪ/.'),q('Nghe và nhập từ.','seat','9:word:seat','seat có /iː/.',{audio:{kind:'word',text:'seat'},skill:'listening'}),q('Viết từ nghĩa là con cừu.','sheep','9:word:sheep','sheep khác ship.')
  ],'Thu ship–sheep, sit–seat. Nghe mẫu và bản ghi luân phiên. Nếu chưa nghe khác, đánh dấu cần người hướng dẫn nghe giúp.','ship ≠ sheep; sit ≠ seat.',['Tôi không chỉ đổi độ dài.','Tôi giữ âm cuối /p/ và /t/.']);
  add(10,'Chọn đúng vị trí môi/răng khi luyện phụ âm qua từ.','Dùng gương: pen/bag khép môi; fish/van răng trên chạm môi dưới. Đặt nhẹ tay lên cổ để tự cảm nhận rung, không ép cổ.','Đọc van với môi khép như bag.','Giữ khe giữa răng trên và môi dưới ở van.','Vị trí tạo âm khác nhau dù tên chữ có phần cuối gần nhau.',[
    q('Viết từ nghĩa là xe tải nhỏ.','van','10:word:van','van bắt đầu /v/.'),q('Nghe và nhập từ.','fish','10:word:fish','fish bắt đầu /f/.',{audio:{kind:'word',text:'fish'},skill:'listening'}),q('Viết từ nghĩa là bút mực.','pen','10:word:pen','pen bắt đầu /p/.'),q('Nghe và nhập từ.','bag','10:word:bag','bag bắt đầu /b/.',{audio:{kind:'word',text:'bag'},skill:'listening'}),q('Nghe và nhập từ.','van','10:word:van','van dùng răng và môi.',{audio:{kind:'word',text:'van'},skill:'listening'}),q('Viết từ nghĩa là con cá.','fish','10:word:fish','fish dùng /f/.')
  ],'Nói pen, bag, fish, van chậm một lượt. Tự kiểm tra môi bằng gương; không kết luận phát âm chuẩn chỉ từ tên từ.','pen/bag: hai môi; fish/van: răng–môi.',['Tôi kiểm tra đúng bộ phận.','Tôi không thêm nguyên âm sau phụ âm.']);
  add(11,'Giữ vị trí âm cuối khi đọc bốn từ đơn.','Đọc từ rồi dừng ở vị trí cuối: cat đầu lưỡi, cup hai môi, pen đầu lưỡi, bag phần sau lưỡi. Không thêm một âm sau từ.','Đọc cup rồi thêm một nguyên âm phía sau.','Dừng khi môi khép ở /p/.','Âm cuối không cần bật thật mạnh nhưng không được bỏ mất.',[
    q('Nghe và tự viết từ.','cup','11:word:cup','cup kết thúc /p/.',{audio:{kind:'word',text:'cup'},skill:'listening'}),q('Viết từ nghĩa là cái túi.','bag','11:word:bag','bag kết thúc /ɡ/.'),q('Nghe và tự viết từ.','pen','11:word:pen','pen kết thúc /n/.',{audio:{kind:'word',text:'pen'},skill:'listening'}),q('Viết từ nghĩa là con mèo.','cat','11:word:cat','cat kết thúc /t/.'),q('Nghe và tự viết từ.','bag','11:word:bag','Giữ cả âm cuối.',{audio:{kind:'word',text:'bag'},skill:'listening'}),q('Viết từ nghĩa là cái cốc.','cup','11:word:cup','cup, dừng ở hai môi.')
  ],'Thu cat–cup–pen–bag. Nghe bản ghi, đánh dấu từ nào bị thêm âm hoặc chưa nghe rõ phần cuối.','cat /t/ · cup /p/ · pen /n/ · bag /ɡ/.',['Tôi không thêm âm sau từ.','Tôi ghi rõ điều chưa chắc để hỏi người hướng dẫn.']);
  add(12,'Nhớ từ ngắn bằng nghe và tự viết, không chỉ nhận ra từ trên màn hình.','Lượt đầu nghe không văn bản; sau khi viết mới so mẫu và nghĩa. Nếu mở chữ để hoàn thành, ghi có hỗ trợ rồi thử lại ở buổi khác.','Mở bản chữ trước rồi coi đó là nghe độc lập.','Nghe trước; khi thiếu giọng có thể luyện đọc, không ghi là đã nghe được.','Hai loại luyện có ích khác nhau.',[
    q('Nghe và nhập từ.','sheep','12:word:sheep','sheep = con cừu.',{audio:{kind:'word',text:'sheep'},skill:'listening'}),q('Viết từ nghĩa là tàu thủy.','ship','12:word:ship','ship, không sheep.'),q('Nghe và nhập từ.','cat','12:word:cat','cat = con mèo.',{audio:{kind:'word',text:'cat'},skill:'listening'}),q('Viết từ nghĩa là bút mực.','pen','12:word:pen','pen.'),q('Nghe và nhập từ.','ship','12:word:ship','ship có /ɪ/.',{audio:{kind:'word',text:'ship'},skill:'listening'}),q('Viết từ nghĩa là con cừu.','sheep','12:word:sheep','sheep có /iː/.')
  ],'Lập danh sách bốn từ, che chữ rồi nghe từng từ. Nhờ người khác chọn thứ tự nếu có thể.','Nghe → tự viết → mở mẫu → sửa.',['Tôi phân biệt có hỗ trợ/độc lập.','Tôi chọn hai từ để quay lại sau nghỉ.']);
  add(13,'Nghe một chữ số và tự ghi số, đổi chiều đọc số thành chữ.','Chia 0–5 và 6–10. Đổi thứ tự để tránh chỉ nhớ bài đếm; dùng zero cho 0 trong buổi này.','Nhớ seven chỉ khi đếm từ one.','Nhìn 7 và gọi seven trực tiếp.','Gọi ngẫu nhiên giúp dùng được số ngoài chuỗi đếm.',[
    q('Viết 6 bằng chữ.','six','13:numbers','6 = six.',{skill:'numbers'}),q('Nghe rồi nhập chữ số.','4','13:numbers','four = 4.',{audio:{kind:'word',text:'four'},skill:'listening'}),q('Viết 9 bằng chữ.','nine','13:numbers','9 = nine.',{skill:'numbers'}),q('Nghe rồi nhập chữ số.','0','13:numbers','zero = 0.',{audio:{kind:'word',text:'zero'},skill:'listening'}),q('Viết 3 bằng chữ.','three','13:numbers','3 = three.',{skill:'numbers'}),q('Nghe rồi nhập chữ số.','8','13:numbers','eight = 8.',{audio:{kind:'word',text:'eight'},skill:'listening'})
  ],'Viết 5 chữ số xáo thứ tự, gọi từng số và đối chiếu. Đổi sang nghe rồi viết số.','7 → seven; four → 4.',['Tôi không cần đếm từ đầu mọi lần.','Tôi thử được cả hai chiều.']);
  add(14,'Đọc số 11–20 và thay tuổi trong câu mẫu.','So eleven/twelve với nhóm teen; nói tuổi bằng cả câu. Dùng nhân vật tưởng tượng nếu tuổi thật ngoài phạm vi số đã học.','I’m fifteen old.','I’m fifteen years old.','Mẫu đầy đủ có years old; khi ngữ cảnh đã rõ có thể nói I’m fifteen.',[
    q('Điền 16 bằng chữ: I’m ___ years old.','sixteen','14:numbers,14:age','16 = sixteen.'),q('Nghe và ghi chữ số.','19','14:numbers','nineteen = 19.',{audio:{kind:'word',text:'nineteen'},skill:'listening'}),q('Viết 14 bằng chữ.','fourteen','14:numbers','14 = fourteen.'),q('Điền 12 bằng chữ: I’m ___ years old.','twelve','14:numbers,14:age','12 = twelve.'),q('Nghe rồi ghi chữ số.','17','14:numbers','seventeen = 17.',{audio:{kind:'word',text:'seventeen'},skill:'listening'}),q('Viết 20 bằng chữ.','twenty','14:numbers','20 = twenty, không có teen.')
  ],'Chọn tuổi 12 hoặc 16. Nói câu đầy đủ rồi dạng ngắn trong ngữ cảnh đang hỏi tuổi.','I’m sixteen years old. / I’m sixteen.',['Tôi dùng đúng số.','Tôi giữ đủ mẫu khi nói câu đầy đủ.']);
  add(15,'Gọi đúng đồ vật thật quanh bàn khi không có nhãn.','Chỉ một vật, che từ, tự gọi tên rồi mở sổ tay kiểm tra. Đổi pen/pencil và desk/chair để nghe cả phần khác nhau.','Gọi bút chì là pen.','Bút chì là pencil; bút mực là pen.','Cần chọn theo vật thật, không theo vị trí thẻ.',[
    q('Viết từ tiếng Anh nghĩa là bàn học/làm việc.','desk','15:objects','desk là bàn.'),q('Nghe và viết đồ vật.','book','15:word:book','book là sách.',{audio:{kind:'word',text:'book'},skill:'listening'}),q('Viết từ chỉ bút chì.','pencil','15:objects','pencil, khác pen.'),q('Nghe và viết đồ vật.','chair','15:word:chair','chair là ghế.',{audio:{kind:'word',text:'chair'},skill:'listening'}),q('Viết từ chỉ bút mực.','pen','15:objects','pen.'),q('Nghe và viết đồ vật.','desk','15:word:desk','desk.',{audio:{kind:'word',text:'desk'},skill:'listening'})
  ],'Dán nhãn tạm ba đồ vật, sau đó tháo nhãn và gọi lại tên. Chọn vật bạn thực sự có.','book · pen · chair.',['Tôi chọn đúng vật.','Tôi thử lại khi bỏ nhãn.']);
  add(16,'Ghép màu với đồ vật khác ví dụ đầu bài theo đúng thứ tự.','Tách phần màu và phần vật. Giữ màu trước vật; chưa thêm be nếu chỉ cần cụm từ.','pen blue','blue pen','Cụm tiếng Anh đặt màu trước tên vật.',[
    q('Viết cụm “bút xanh dương”.','blue pen','16:phrase,15:objects','blue đứng trước pen.'),q('Viết cụm “sách đỏ”.','red book','16:phrase,15:objects','red + book.'),q('Điền màu trắng: ___ chair.','white','16:colors','white = trắng.'),q('Viết cụm “bút chì đen”.','black pencil','16:phrase,15:objects','black + pencil.'),q('Điền xanh lá: ___ book.','green','16:colors','green = xanh lá.'),q('Viết cụm “bàn màu trắng”.','white desk','16:word:white,15:objects','white desk.')
  ],'Chọn hai đồ vật thật có màu đã học; nói cụm màu + vật, đổi màu trong một ví dụ tưởng tượng.','blue pen; red book.',['Tôi đặt màu trước vật.','Tôi thay được cả hai phần của cụm.']);
  add(17,'Giới thiệu quan hệ bằng my + từ người thân, không áp đặt tuổi lớn/nhỏ.','Tạo một sơ đồ gia đình thật hoặc tưởng tượng. Dùng my trước mỗi quan hệ khi nói về mình.','my sisters dùng để nói đúng một chị gái.','my sister','sisters thêm s để nói nhiều chị/em gái; ở đây một người nên dùng sister. sister không nói rõ lớn/nhỏ tuổi hơn mình.',[
    q('Viết cụm “chị hoặc em gái tôi”.','my sister','17:my,17:family','my + sister.'),q('Viết cụm “gia đình tôi”.','my family','17:my','my + family.'),q('Viết cụm “anh hoặc em trai tôi”.','my brother','17:my','my + brother.'),q('Nghe rồi viết từ quan hệ.','mother','17:word:mother','mother là mẹ.',{audio:{kind:'word',text:'mother'},skill:'listening'}),q('Viết cụm “bố tôi”.','my father','17:my','my + father.'),q('Nghe rồi viết từ quan hệ.','sister','17:word:sister','sister là chị/em gái.',{audio:{kind:'word',text:'sister'},skill:'listening'})
  ],'Ghi ba cụm về gia đình tưởng tượng. Người đọc phải nhận ra quan hệ nào nhưng không cần biết tên thật.','my mother; my father; my sister.',['Tôi có my.','Tôi không suy ra tuổi chỉ từ sister/brother.']);
  add(18,'Đọc và tự giới thiệu một đồ vật với màu khác mẫu.','Ghép This is + my + màu + vật. Tự tách nghĩa từng phần để không chỉ đọc theo trí nhớ cả câu.','This is a my red book.','This is my red book.','Không dùng a trước my trong mẫu này.',[
    q('Viết: Đây là bút xanh dương của tôi.','This is my blue pen.','18:this,18:context,16:colors','This is + my + blue + pen.'),q('Viết cụm “sách xanh lá của tôi”.','my green book','18:context,16:colors','my + màu + vật.'),q('Điền: This ___ my father.','is','18:this,17:family','This is giới thiệu người/vật.'),q('Sửa: a my book.','my book','18:a','Không ghép a với my.'),q('Viết: Đây là mẹ tôi.','This is my mother.','18:this','This is + my mother.'),q('Điền: my ___ pencil = bút chì đen của tôi.','black','18:context,16:colors','black = đen.')
  ],'Giới thiệu hai đồ vật quanh bạn. Đổi màu/vật với ví dụ làm mẫu, rồi nhờ người nghe chỉ đúng đồ vật.','This is my blue pen. This is my green book.',['Tôi dùng This is.','Tôi giữ my + màu + vật.','Tôi không thêm a trước my.']);

  add(19,'Chọn từ chỉ người theo người nói/nghe trong tình huống mới.','Hỏi ba điều: ai đang nói, đang nói với ai, đang nhắc ai? Không đoán giới tính bằng tên.','Tôi và mẹ tôi → they.','Tôi và mẹ tôi → we.','we gồm người nói; they trong tình huống này không gồm người nói.',[
    q('Bạn và một người bạn cùng nói về nhóm của mình. Viết một từ thay nhóm này.','we','19:group','Nhóm gồm người nói.'),q('Bạn nói trực tiếp với hai học viên. Viết từ chỉ hai người đang nghe.','you','19:group','you có thể là nhiều người.'),q('Nhắc một người phụ nữ đã được giới thiệu. Dùng từ nào?','she','19:people','she là cô ấy.'),q('Nhắc một quyển sách đang trên bàn. Dùng từ nào?','it','19:group','it thay một đồ vật.'),q('Hai người khác, không gồm bạn hoặc người nghe trong tình huống. Dùng từ nào?','they','19:group','they thay nhóm được nói tới.'),q('Người đang nói về chính mình. Dùng từ nào?','I','19:people','I là tôi.')
  ],'Vẽ ba vai: người nói, người nghe, người được nhắc. Viết đại từ phù hợp rồi giải thích bằng tiếng Việt.','Tôi và bạn cùng nhóm → we; nói với bạn → you.',['Tôi xác định vai trước.','Tôi không đoán giới tính từ tên.']);
  add(20,'Tự tạo câu tên/trạng thái/nghề, không bỏ am khi đổi từ sau.','Tách câu thành I | am | thông tin. Với nghề teacher/student thêm a; happy/tired không thêm a.','I a teacher.','I am a teacher.','Cần am để nối I với nghề.',[
    q('Nói mình là giáo viên: viết một câu hoàn chỉnh.','I am a teacher.','20:am,20:job','I + am + a teacher.'),q('Dùng I am để nói mình vui.','I am happy.','20:am,20:word:happy','Không bỏ am.'),q('Sửa câu thiếu một từ: I tired.','I am tired.','20:am','Thêm am.'),q('Viết câu đầy đủ với tên Mai: Tôi là Mai.','I am Mai.','20:am','Tên có thể đổi mà mẫu giữ nguyên.'),q('Điền: I am ___ student.','a','20:job','a trước student.'),q('Viết “Tôi là học viên” bằng mẫu I am.','I am a student.','20:job','I am + a student.')
  ],'Không nhìn mẫu, viết tên và một trạng thái thật. Đổi tired thành happy để tạo câu mới.','I am Mai. I am tired.',['Tôi có am.','Tôi không thêm a trước trạng thái.','Tôi thay thông tin mà vẫn giữ mẫu.']);
  add(21,'Đổi người được nói tới và tự chọn am/are/is.','Đọc phần chỉ người trước: I→am; you/we/they→are; he/she/it→is. Sau đó mới ghép trạng thái/nghề.','They is tired.','They are tired.','Dạng be phụ thuộc người/nhóm được nói tới.',[
    q('Viết: Họ mệt.','They are tired.','21:be,20:word:tired','They + are.'),q('Viết: Anh ấy vui.','He is happy.','21:be,20:word:happy','He + is.'),q('Điền: It ___ my book.','is','21:be,18:context','It đi với is.'),q('Điền: You ___ a teacher.','are','21:be,21:a','You đi với are.'),q('Viết: Chúng tôi là các học viên.','We are students.','21:a','We are + students, không a.'),q('Sửa: She are a student.','She is a student.','21:be,21:a','She đi với is.')
  ],'Viết một câu với I, một với she và một với they. Gạch chân am/is/are rồi đối chiếu bảng.','I am tired. She is happy. They are students.',['Tôi chọn be theo người.','Tôi dùng a trước nghề một người.']);
  add(22,'Phủ định câu be sau khi thay người và trạng thái.','Tìm be trong câu khẳng định, thêm not ngay sau be. Với I dùng I’m not, không ghép I’m am not.','You not are happy.','You are not happy.','not đứng sau are.',[
    q('Viết: Bạn không mệt.','You are not tired.','22:not,21:be','You + are + not + tired.'),q('Viết: Tôi không phải học viên.','I am not a student.','22:not,22:keep','Giữ a student.'),q('Điền: He is ___ happy.','not','22:not,20:word:happy','not sau is.'),q('Sửa: They not are tired.','They are not tired.','22:not,21:be','are trước not.'),q('Viết: Cô ấy không phải giáo viên.','She is not a teacher.','22:not,22:keep','Giữ a teacher.'),q('Điền: I ___ not tired.','am','22:not','I am not.')
  ],'Viết một điều không đúng về nhân vật tưởng tượng rồi phủ định nó. Tự kiểm tra vị trí not và a.','She is a teacher. → She is not a teacher.',['Tôi giữ be.','Tôi đặt not sau be.','Tôi không mất a trước nghề.']);
  add(23,'Tự đặt câu hỏi be và trả lời đúng người.','Đảo be ra đầu để hỏi; trả lời về mình đổi you sang I. Câu đáp khẳng định ngắn không kết thúc bằng I’m.','Are you tired? — Yes, you are.','Are you tired? — Yes, I am.','Người hỏi gọi bạn là you; bạn tự nói về mình là I.',[
    q('Đổi He is happy. thành câu hỏi.','Is he happy?','23:question,21:be','Is ra đầu.'),q('Are you a teacher? Trả lời không.',['No, I am not.',"No, I'm not."],'23:reply,22:not','Nói về mình dùng I.'),q('Điền: ___ they tired?','Are','23:question,21:be','They dùng are.'),q('Is she tired? Trả lời có.','Yes, she is.','23:reply','Không đổi she thành I.'),q('Đổi You are a student. thành câu hỏi.','Are you a student?','23:question,20:job','Are trước you.'),q('Are you happy? Trả lời có.','Yes, I am.','23:reply,23:no-short','Giữ am đầy đủ trong câu đáp ngắn.')
  ],'Hai vai hỏi/đáp về trạng thái thật hoặc tưởng tượng. Sau đó hỏi về she và giữ she khi trả lời.','Are you tired? — No, I’m not. Is she happy? — Yes, she is.',['Tôi đảo be.','Tôi đổi you→I khi cần.','Tôi không nói Yes, I’m.']);
  add(24,'Đọc lời giới thiệu mới và tự viết ba câu liên kết về người thân.','Giới thiệu quan hệ bằng This is my ...; sau đó thay bằng he/she theo người đã nêu. Kiểm tra mỗi câu có be khi nối với nghề.','This is my father. She is a teacher.','This is my father. He is a teacher.','Trong tình huống bố đã được nói là nam, dùng he.',[
    q('Viết: Đây là chị/em gái tôi.','This is my sister.','18:this,17:my','This is + my sister.'),q('Điền: My father ___ a teacher.','is','24:follow','Một người dùng is.'),q('Viết: Mẹ tôi là giáo viên.','My mother is a teacher.','24:follow','My mother + is + a teacher.'),q('Điền từ chỉ người: This is my mother. ___ is a teacher.','She','24:follow','She nhắc my mother.'),q('Sửa: We are a students.','We are students.','24:plural','Không a trước students.'),q('Điền: I ___ a student.','am','20:am','I + am.')
  ],'Viết ba câu về bản thân và một người thân tưởng tượng. Người đọc phải biết ai có nghề gì.','I’m Mai. This is my father. He is a teacher.',['Tôi giới thiệu quan hệ trước khi dùng he/she.','Tôi có be.','Tôi có a trước nghề số ít.']);
  add(25,'Mở và khép cuộc làm quen phù hợp thời điểm, trả lời hỏi thăm đúng ý.','Chọn lời chào theo lúc gặp. How are you hỏi trạng thái, Nice to meet you dành lần đầu gặp. Đừng trả lời mọi câu bằng một lời chào.','Gặp ai buổi tối và mở đầu bằng Good night.','Good evening.','Good night thường lúc chia tay/đi ngủ.',[
    q('Gặp đồng nghiệp lúc sáng: viết lời chào theo buổi.','Good morning.','25:greet','Buổi sáng dùng Good morning.',{skill:'conversation'}),q('How are you? Bạn ổn: viết lời đáp có cảm ơn.',["I'm fine, thank you.",'I am fine, thank you.'],'25:how','Hỏi trạng thái, đáp I’m fine.',{skill:'conversation'}),q('Điền lời đáp: Nice to meet you, ___.','too','25:meet','too = cũng.'),q('Buổi chiều, viết lời chào theo buổi.','Good afternoon.','25:greet','Good afternoon = chào chiều.',{skill:'conversation'}),q('How are you? Bạn mệt: viết một câu đúng ý.','I am tired.','25:how','Trả lời thật theo trạng thái.',{skill:'conversation'}),q('Viết lời chào khi mới gặp vào buổi tối.','Good evening.','25:greet','Không dùng Good night để mở đầu.',{skill:'conversation'})
  ],'Luyện với người khác hoặc tự hai vai: chào, tên, hỏi thăm, đáp và tạm biệt. Lượt sau đổi buổi và trạng thái.','Good morning. I’m Mai. — Hi, Mai. I’m Lan.',['Lời chào hợp buổi.','Lời đáp đúng câu hỏi.','Tôi thay trạng thái được.']);
  add(26,'Hỏi tên rồi xin đánh vần khi chưa rõ cách viết.','Hỏi tên khác hỏi cách viết tên. Sau câu Can you spell that, please?, đáp từng chữ; không chỉ nói lại cả tên.','Can you spell that, please? — I’m fine.','M–A–I.','Người hỏi cần cách viết, không hỏi thăm trạng thái.',[
    q('Viết câu hỏi tên với What is/What’s.','What is your name?','26:name','What is + your name?',{skill:'conversation'}),q('Tên được đánh vần M–A–I. Viết liền tên.','Mai','26:check','Giữ thứ tự.',{skill:'letters'}),q('Điền: My ___ is An.','name','26:name','My name is + tên.'),q('Viết yêu cầu đánh vần theo mẫu Can you ... please?','Can you spell that, please?','26:spell','Dùng cả câu yêu cầu.',{skill:'conversation'}),q('Điền: What’s ___ name?','your','26:name','your name = tên bạn.'),q('Tên được đánh vần L–A–N. Viết liền tên.','Lan','26:check','L rồi A rồi N.',{skill:'letters'})
  ],'Đóng hai vai: hỏi tên MAI, xin đánh vần rồi viết lại. Lượt hai đổi sang AN.','What’s your name? — My name is Mai. Can you spell that, please? — M–A–I.',['Tôi yêu cầu đúng việc.','Tôi giữ thứ tự chữ.']);
  add(27,'Trả lời riêng nơi xuất thân và nơi đang sống khi hai nơi khác nhau.','Đọc từ khóa from hoặc live; chọn thông tin đúng mục đích, dù cả hai câu đều đúng ngữ pháp.','Where do you live? — I’m from Hue.','I live in Hanoi.','Câu hỏi live hỏi nơi đang sống, không hỏi xuất thân.',[
    q('Nhân vật đến từ Hà Nội. Viết câu với I’m from.','I am from Hanoi.','27:from,27:place','from + nơi xuất thân.'),q('Nhân vật đang sống ở Huế. Viết câu với I live.','I live in Hue.','27:live,27:place','live in + nơi sống.'),q('Điền: I’m ___ Hue.','from','27:from','from nêu xuất thân.'),q('Điền: I live ___ Vietnam.','in','27:live','in + quốc gia.'),q('Viết câu hỏi nơi xuất thân theo mẫu Where are ...?','Where are you from?','27:from','Học trọn mẫu câu.'),q('Viết câu hỏi nơi sống theo mẫu Where do ...?','Where do you live?','27:live','Hỏi nơi đang sống.')
  ],'Nhân vật quê Hà Nội, sống Huế. Tạo hai câu rồi đổi vai đặt đúng hai câu hỏi.','I’m from Hanoi. I live in Hue.',['Tôi không tráo from và live in.','Người nghe biết thông tin nào là quê/nơi sống.']);
  add(28,'Nói nghề và việc học như hai thông tin khác nhau.','I am + a/an nghề; I work/study + thông tin hành động. Không dùng am trước work/study trong mẫu đang học.','I am study English.','I study English.','study là hành động; mẫu này không thêm am.',[
    q('Viết: Tôi là kỹ sư.','I am an engineer.','28:job','an trước engineer.'),q('Viết: Tôi làm việc ở Huế.','I work in Hue.','28:work,27:place','I + work + in Hue.'),q('Điền: I ___ English. (study)','study','28:work','Không am trước study.'),q('Điền: I am ___ teacher.','a','20:job','a teacher.'),q('Viết câu hỏi nghề trong lúc làm quen.','What do you do?','28:job','Mẫu hỏi nghề.'),q('Sửa: I am work in Hanoi.','I work in Hanoi.','28:work','Bỏ am.')
  ],'Đổi nghề của một nhân vật rồi nói thêm nơi làm việc và việc học.','I’m a teacher. I work in Hue. I study English.',['Tôi dùng a/an đúng từ nghề.','Tôi không thêm am trước hành động.']);
  add(29,'Dừng cuộc nói chuyện để xin chậm hoặc nhắc lại khi chưa hiểu.','Nêu nhu cầu cụ thể. Muốn chậm: Please speak slowly. Muốn nghe lại: Can you say that again, please? Cảm ơn sau khi được giúp.','Cần nhắc lại nhưng chỉ nói You’re welcome.','Can you say that again, please?','You’re welcome đáp cảm ơn, không xin nhắc lại.',[
    q('Xin người kia nói chậm bằng câu bắt đầu Please.','Please speak slowly.','29:repair','slowly xin giảm tốc.',{skill:'conversation'}),q('Xin nhắc lại bằng mẫu Can you ... please?','Can you say that again, please?','29:repair','again xin nói lại.',{skill:'conversation'}),q('Viết mẫu “Tôi chưa hiểu”.',['I do not understand.',"I don't understand."],'29:repair','don’t = do not.'),q('Đáp Thank you theo mẫu trong bài.','You’re welcome.','29:polite','Đáp lại cảm ơn.'),q('Lỡ gây phiền, viết lời xin lỗi ngắn.','Sorry.','29:polite','Sorry sau lỗi gây phiền.'),q('Muốn thu hút chú ý trước khi hỏi, dùng mẫu hai từ.','Excuse me.','29:polite','Excuse me trước khi hỏi/nhờ.')
  ],'Một vai nói tên nhanh, vai kia xin nói chậm và nhắc lại rồi cảm ơn. Đổi vai, không cố đoán mọi thứ.','I don’t understand. Please speak slowly. Thank you.',['Tôi xin đúng loại hỗ trợ.','Tôi tiếp tục được sau khi được giúp.']);
  add(30,'Tự duy trì làm quen khi thông tin và thứ tự câu hỏi thay đổi.','Nghe mục đích từng câu, không học thuộc thứ tự hội thoại. Có thể xin nhắc lại rồi trả lời đúng thông tin.','What do you do? — I live in Hanoi.','I’m a teacher.','Câu hỏi này hỏi nghề, không hỏi nơi sống.',[
    q('Nhân vật là học viên. What do you do? Viết lời đáp về mình.','I am a student.','28:job','Đúng trọng tâm nghề/học tập.',{skill:'conversation'}),q('Nhân vật sống Huế. Where do you live? Viết lời đáp.','I live in Hue.','27:live,27:place','Đúng nơi đang sống.',{skill:'conversation'}),q('Nhân vật tên An. What’s your name? Viết câu My name is...','My name is An.','26:name','Đáp tên.'),q('Nhân vật đến từ Việt Nam. Viết câu với I’m from.','I am from Vietnam.','27:from','Đáp xuất thân.'),q('Chưa nghe được câu hỏi, xin người kia nói lại.','Can you say that again, please?','29:repair','Xin nhắc lại.'),q('Viết câu: Tôi học tiếng Anh.','I study English.','28:work','Không thêm am trước study.')
  ],'Dùng nhân vật An, quê Việt Nam, sống Huế, là học viên. Luyện hỏi/đáp theo thứ tự khác mẫu và có một lần xin hỗ trợ.','My name is An. I’m from Vietnam. I live in Hue. I’m a student.',['Tôi trả lời đúng trọng tâm.','Tôi thay được thông tin.','Tôi có một câu xin hỗ trợ.']);
  add(31,'Kể ba hành động theo thứ tự một ngày bằng cụm hoàn chỉnh.','Học cả cụm get up/have breakfast/go to bed. Nhớ một hành động rồi tự tạo câu I + cụm thay vì chỉ dịch từng từ.','I breakfast.','I have breakfast.','Cần cụm hành động have breakfast.',[
    q('Viết: Tôi thức dậy.','I get up.','31:verbs','Giữ get up.'),q('Viết: Tôi đi ngủ.','I go to bed.','31:verbs','Giữ go to bed.'),q('Điền: I ___ a book.','read','31:chunks','read a book = đọc sách.'),q('Viết: Tôi ăn sáng.','I have breakfast.','31:verbs','have breakfast.'),q('Viết: Tôi làm việc mỗi ngày.','I work every day.','31:verbs,31:routine','every day nêu thói quen.'),q('Điền: I study ___. (tiếng Anh)','English','31:chunks,28:work','study English.')
  ],'Kể ba hành động một ngày thật hoặc tưởng tượng; người nghe xếp ba nhãn theo thứ tự bạn nói.','I get up. I have breakfast. I study English.',['Tôi giữ cả cụm.','Tôi không thêm am trước hành động.']);
  add(32,'Đổi I sang we/they mà giữ dạng hành động cơ bản.','Phân biệt câu nghề với câu hành động. Với I/you/we/they, dùng work/study/read như trong từ điển trong mẫu này.','We studies English.','We study English.','We giữ study, không thêm s.',[
    q('Viết: Bạn làm việc mỗi ngày.','You work every day.','32:simple,32:time','You + work.'),q('Viết: Chúng tôi học vào buổi sáng.','We study in the morning.','32:simple,32:time','We + study + thời gian.'),q('Sửa: They are work at night.','They work at night.','32:be','Không are trước work.'),q('Điền: We ___ a book. (read)','read','32:simple,31:chunks','We giữ read.'),q('Viết: Tôi học tiếng Anh vào ban đêm.','I study English at night.','32:simple,32:time','I + study + English + at night.'),q('Điền: They ___ in Hanoi. (work)','work','32:simple','They + work.')
  ],'Viết một câu I và đổi sang we, thêm thời gian. Giải thích bằng tiếng Việt vì sao không thêm are trước hành động.','I read every day. → We read every day.',['Tôi giữ dạng cơ bản.','Tôi dùng thời gian đúng ý.']);
  add(33,'Đổi chủ thể và áp dụng cả works, studies, goes, has đúng mẫu.','Với he/she trong khẳng định, kiểm tra dạng từng từ; đừng thêm s máy móc vào have/study.','She haves breakfast.','She has breakfast.','have đổi thành has trong mẫu này.',[
    q('Đổi I read every day. sang nói về cô ấy.','She reads every day.','33:s,32:time','read thêm s.'),q('Đổi I have breakfast. sang nói về anh ấy.','He has breakfast.','33:changes','have → has.'),q('Điền: She ___ to bed. (go)','goes','33:changes','go → goes.'),q('Viết: Anh ấy học tiếng Anh.','He studies English.','33:changes','study → studies.'),q('Điền: He ___ in Hue. (work)','works','33:s,27:place','work thêm s.'),q('Sửa: She studys English.','She studies English.','33:changes','study → studies.')
  ],'Đổi hai câu thói quen của I sang he/she. Khoanh chỗ đổi và đọc lại cả câu.','I study English. → She studies English.',['Tôi kiểm tra dạng đặc biệt.','Tôi không đổi phần thông tin không cần đổi.']);
  add(34,'Tạo phủ định hành động với người khác, không giữ s sau doesn’t.','Dùng don’t cho I/you/we/they, doesn’t cho he/she; hành động sau đều trở về cơ bản.','He doesn’t has breakfast.','He doesn’t have breakfast.','doesn’t đã mang thông tin người; have trở về cơ bản.',[
    q('Viết: Chúng tôi không học vào ban đêm.','We do not study at night.','34:do,32:time','We + do not + study.'),q('Viết: Anh ấy không đi ngủ.','He does not go to bed.','34:does,31:verbs','Sau does not dùng go.'),q('Sửa: She doesn’t has breakfast.','She does not have breakfast.','34:does','has → have.'),q('Điền: They ___ not work.','do','34:do','They do not.'),q('Viết: Cô ấy không làm việc ở Huế.','She does not work in Hue.','34:does,27:place','She + does not + work.'),q('Điền: I ___ understand. (dạng gọn phủ định)',"don't",'34:do','I don’t understand.')
  ],'Phủ định hai thói quen: một câu I, một câu she. Gạch chân hành động cơ bản sau don’t/doesn’t.','I don’t work at night. She doesn’t study at night.',['Tôi chọn do/does theo người.','Tôi bỏ s sau doesn’t.']);
  add(35,'Đặt câu hỏi hành động, trả lời có/không và phân biệt câu hỏi be.','Nhìn nội dung sau người: nếu là hành động work/study dùng Do/Does; nếu nghề/trạng thái trong mẫu be dùng Are/Is.','Does she works?','Does she work?','Sau Does dùng work cơ bản.',[
    q('Hỏi từ He works in Hue.','Does he work in Hue?','35:ask,27:place','Does + he + work.'),q('Do you work at night? Viết lời đáp không.','No, I do not.','35:reply','Đáp về mình dùng I don’t.'),q('Điền: ___ you a teacher?','Are','35:be','Nghề dùng be trong mẫu này.'),q('Does she study English? Viết lời đáp có.','Yes, she does.','35:reply','Giữ she và does.'),q('Viết câu hỏi: Bạn có đọc mỗi ngày không?','Do you read every day?','35:ask,32:time','Do + you + read.'),q('Sửa: Does he has breakfast?','Does he have breakfast?','35:ask,34:does','has về have.')
  ],'Hỏi hai câu về thói quen, một câu về nghề; tự viết câu trả lời ngắn phù hợp với từ dùng để hỏi.','Do you study English? — Yes, I do. Are you a teacher? — No, I’m not.',['Tôi phân biệt be với hành động.','Tôi chọn đúng dạng trả lời ngắn.']);
  add(36,'Tạo đoạn thói quen có câu khẳng định và phủ định, đọc đúng người trong đoạn mới.','Đọc người trước rồi thời gian. Khi tự viết, kiểm tra từng câu riêng: ai → khẳng định/phủ định → dạng hành động.','My brother don’t study.','My brother doesn’t study.','Một người được nhắc tới dùng doesn’t.',[
    q('Viết: Cô ấy học vào buổi sáng.','She studies in the morning.','33:changes,32:time','She + studies + thời gian.'),q('Viết: Họ không làm việc vào ban đêm.','They do not work at night.','34:do,32:time','They + do not + work.'),q('Điền: My brother ___ English. (study)','studies','33:changes,36:story','My brother là một người.'),q('Sửa: He doesn’t goes to bed.','He does not go to bed.','34:does','goes về go.'),q('Viết: Chúng tôi đọc mỗi ngày.','We read every day.','32:simple,32:time','We giữ read.'),q('Hỏi từ She works in Hanoi.','Does she work in Hanoi?','35:ask','Does + she + work.')
  ],'Viết bốn câu thói quen của bạn và người khác: có thời gian, một phủ định, một câu hỏi để hỏi lại người nghe.','I study at night. My brother works in Hue. He doesn’t study at night. Do you study English?',['Tôi giữ s ở câu khẳng định he/she.','Tôi bỏ s sau does/doesn’t.','Tôi nói rõ ai và thời gian.']);
  add(37,'Nói giờ của một hoạt động khác ví dụ và phân biệt giờ đúng/giờ rưỡi.','Tách câu hành động khỏi giờ; nối bằng at. half past eight là 8:30, không phải 7:30.','I get up in eight.','I get up at eight.','at đứng trước giờ trong mẫu.',[
    q('Viết: Tôi thức dậy lúc 8 giờ.','I get up at eight.','37:at,13:numbers','at + eight.'),q('Nghe giờ, ghi dạng số như 8:30.','8:30','37:time,13:numbers','half past eight là 8:30.',{audio:{kind:'phrase',text:'half past eight'},skill:'listening'}),q('Điền: I go to bed ___ ten.','at','37:at,31:verbs','at trước giờ.'),q('Viết 6 giờ đúng bằng cụm số chữ + o’clock.','six o’clock','37:time,13:numbers','six o’clock = 6:00.'),q('Nghe giờ rồi ghi dạng số như 7:00.','9:00','37:time,13:numbers','nine o’clock = 9:00.',{audio:{kind:'phrase',text:'nine o’clock'},skill:'listening'}),q('Viết: Tôi ăn sáng lúc 7 giờ rưỡi.','I have breakfast at half past seven.','37:at','at half past seven.')
  ],'Viết hai giờ sinh hoạt; nói rõ sáng/tối khi cần bằng a.m./p.m. trong lịch viết. Hỏi giờ của người khác.','I get up at eight. I have breakfast at half past eight.',['Tôi dùng at.','Tôi phân biệt giờ đúng/rưỡi.']);
  add(38,'Hỏi sở thích mới và nói được điều thích/không thích mà không trộn be.','like là hành động: I like, she likes; phủ định doesn’t like. Với mẫu thích hoạt động, dùng reading/studying English như đã dạy.','She doesn’t likes tea.','She doesn’t like tea.','Sau doesn’t dùng like cơ bản.',[
    q('Viết: Cô ấy thích đọc sách.','She likes reading.','38:like,38:forms','She likes + reading.'),q('Hỏi: Bạn có thích cà phê không?','Do you like coffee?','38:forms,38:drinks','Do + you + like + coffee.'),q('Viết: Tôi không thích trà.','I do not like tea.','38:forms','I don’t like tea.'),q('Điền: He ___ coffee. (like)','likes','38:forms,33:s','He + likes.'),q('Sửa: She is like tea.','She likes tea.','38:forms','Không is trước like.'),q('Viết: Tôi thích học tiếng Anh.','I like studying English.','38:like','like + studying English.')
  ],'Tạo hai sở thích khác mẫu đầu bài, một điều không thích và một câu hỏi. Dùng người tưởng tượng nếu muốn.','I like reading. I don’t like coffee. Do you like tea?',['Tôi giữ dạng sau like đã học.','Tôi hỏi và đáp đúng ý.']);
  add(39,'Gọi món khác và phản hồi khi nhân viên hỏi thêm.','Chọn đồ uống trước rồi đưa vào mẫu gọi món. Anything else? là cơ hội thêm món hoặc từ chối lịch sự; không chỉ đọc thuộc đoạn.','Anything else? — You’re welcome.','No, thank you.','Nếu không cần thêm, từ chối bằng No, thank you.',[
    q('Gọi một cà phê, dùng mẫu ngắn có please.','A coffee, please.','39:order','a coffee = một suất cà phê.',{skill:'conversation'}),q('Nhân viên hỏi Anything else? Bạn không cần thêm. Viết lời đáp.','No, thank you.','39:reply','Từ chối lịch sự.',{skill:'conversation'}),q('Điền: I’d like a cup ___ tea.','of','39:order','a cup of tea.'),q('Gọi một tách trà bằng mẫu I would like, có please.','I would like a cup of tea, please.','39:order','Mẫu lịch sự.'),q('Nhân viên đưa món và nói Here you are. Viết lời cảm ơn.','Thank you.','39:reply,29:polite','Cảm ơn sau khi nhận món.',{skill:'conversation'}),q('Gọi một tách trà bằng mẫu ngắn, có please.','A cup of tea, please.','39:order','Giữ a cup of tea.')
  ],'Lượt một gọi trà và không thêm món; lượt hai gọi cà phê rồi thêm trà. Đổi vai khách/nhân viên.','A coffee, please. — Anything else? — A cup of tea, please.',['Tôi đổi được món.','Tôi phản hồi đúng lời hỏi thêm.','Tôi dùng please/thank you.']);
  add(40,'Mô tả vị trí sau khi đồ vật được chuyển chỗ.','Nhìn quan hệ thật: trong, trên, dưới hay cạnh. Giữ Where is để hỏi một vật và is trong câu trả lời.','The pen on the desk.','The pen is on the desk.','Câu hoàn chỉnh cần is trong mẫu này.',[
    q('Bút nằm dưới bàn. Viết với The pen...','The pen is under the desk.','40:position','under = dưới.'),q('Túi nằm trên bàn. Viết với The bag...','The bag is on the desk.','40:position','on = trên, tiếp xúc mặt.'),q('Hỏi túi của bạn ở đâu, dùng my.','Where is my bag?','40:where,40:position','Where is + my bag?'),q('Điền: The pen is ___ the bag. (trong)','in','40:examples','in = trong.'),q('Ghế bên cạnh bàn: điền The chair is ___ the desk.','next to','40:examples','Giữ hai từ next to.'),q('Sửa: The bag under the desk.','The bag is under the desk.','40:position','Thêm is.')
  ],'Đặt bút trên bàn rồi trong túi. Nói vị trí mỗi lần; nhờ người nghe chỉ đúng theo lời bạn.','The pen is on the desk. → The pen is in the bag.',['Tôi chọn theo vị trí mới.','Tôi có is.','Tôi giữ cả cụm next to.']);
  add(41,'Viết lời nhắn cho người khác với giờ/vật khác, không suy diễn thông tin thiếu.','Gọi người nhận, nói việc/giờ, thêm yêu cầu và ký tên. Người đọc phải biết ai cần làm gì; nếu chưa rõ sáng/tối, ghi rõ thay vì đoán.','Tin có at eight nhưng đoán chắc là 8 giờ sáng.','Chỉ biết 8 giờ; cần thêm a.m./p.m. nếu muốn rõ.','Không có thông tin thì không suy diễn.',[
    q('Điền: Let’s meet at ___. (8, viết bằng chữ)','eight','41:chunks,13:numbers','at eight = lúc 8 giờ.'),q('Viết lời nhờ mang bút của tôi.','Please bring my pen.','41:chunks,15:objects','Please bring + my pen.'),q('Viết lời hẹn gặp ngày mai.','Let’s meet tomorrow.','41:chunks','tomorrow = ngày mai.'),q('Điền: Please ___ my book.','bring','41:chunks','bring = mang đến.'),q('Viết lời nhờ mang sách của tôi.','Please bring my book.','41:chunks','Please bring my book.'),q('Điền: Let’s meet ___ seven.','at','41:message,37:at','at trước giờ.')
  ],'Viết tin cho Mai hẹn 8 giờ, nhờ mang bút rồi ký tên An. Tự đổi giờ/vật cho tin thứ hai.','Hi, Mai. Let’s meet at eight. Please bring my pen. Thank you. An.',['Có người nhận/người gửi.','Giờ và yêu cầu rõ.','Không suy diễn điều chưa viết.']);
  add(42,'Tự giới thiệu, trao đổi nhu cầu và chọn kế hoạch ôn từ chỗ chưa chắc.','Kết hợp từng mẫu nhỏ đã học, rồi kiểm tra lại be/hành động. Hoàn thành khóa không thay đánh giá nghe/nói/viết trực tiếp với người hướng dẫn.','She doesn’t studies English.','She doesn’t study English.','Dạng cơ bản sau doesn’t; kiểm tra cả câu thay vì chỉ một từ.',[
    q('Nhân vật sống Huế: viết một câu với I live.','I live in Hue.','27:live,27:place','live in + nơi sống.'),q('Viết: Cô ấy không thích cà phê.','She does not like coffee.','38:forms','does not + like.'),q('Hỏi tên bằng What is/What’s.','What is your name?','26:name','Hỏi đúng thông tin.'),q('Viết: Anh ấy học tiếng Anh mỗi ngày.','He studies English every day.','33:changes,32:time','He + studies.'),q('Bút trong túi: viết The pen...','The pen is in the bag.','40:examples','in = trong.'),q('Xin người kia nói lại theo mẫu Can you...','Can you say that again, please?','29:repair','Dùng yêu cầu hỗ trợ đã học.')
  ],'Tạo đoạn giới thiệu không nhìn mẫu: tên, nơi sống, thói quen, sở thích. Sau đó gọi đồ uống và xin nhắc lại trong hội thoại. Chọn 3 mục ôn từ kết quả thật.','I’m Mai. I live in Hue. I study English every day. I like reading.',['Tôi thay thông tin thật/giả được.','Tôi tự kiểm tra be và hành động.','Tôi biết phần nói cần người khác nghe giúp.']);

  // Foundation history is never mutated. New probes have edition-specific IDs.
  const conversations={
    25:[['Good morning. I’m Lan.','Chào buổi sáng. Tôi là Lan.'],['Hello, Lan. I’m Mai. Nice to meet you.','Chào Lan. Tôi là Mai. Rất vui được gặp bạn.'],['Nice to meet you, too. How are you?','Tôi cũng rất vui. Bạn thế nào?'],['I’m fine, thank you.','Tôi ổn, cảm ơn bạn.'],['Goodbye, Mai.','Tạm biệt Mai.'],['Bye, Lan.','Tạm biệt Lan.']],
    26:[['Hello. What’s your name?','Chào bạn. Tên bạn là gì?'],['My name is Mai.','Tên tôi là Mai.'],['Can you spell that, please?','Bạn đánh vần giúp tôi được không?'],['M, A, I.','M–A–I.'],['Thank you, Mai.','Cảm ơn Mai.'],['You’re welcome.','Không có gì.']],
    27:[['Where are you from?','Bạn đến từ đâu?'],['I’m from Hue.','Tôi đến từ Huế.'],['Where do you live?','Bạn sống ở đâu?'],['I live in Hanoi.','Tôi sống ở Hà Nội.']],
    28:[['What do you do?','Bạn làm nghề gì?'],['I’m an engineer. I work in Hanoi.','Tôi là kỹ sư. Tôi làm việc ở Hà Nội.'],['Are you a student?','Bạn có phải học viên không?'],['No, I’m not. I study English.','Không. Tôi học tiếng Anh.']],
    29:[['Hello. My name is Mai.','Chào bạn. Tên tôi là Mai.'],['Sorry. Can you say that again, please?','Xin lỗi. Bạn nói lại giúp tôi được không?'],['My name is Mai.','Tên tôi là Mai.'],['Can you spell that, please?','Bạn đánh vần giúp tôi được không?'],['M, A, I.','M–A–I.'],['Thank you, Mai.','Cảm ơn Mai.']],
    30:[['Hello. I’m Mai.','Chào bạn. Tôi là Mai.'],['Hi, Mai. I’m An. Nice to meet you.','Chào Mai. Tôi là An. Rất vui được gặp bạn.'],['Nice to meet you, too. Where are you from?','Tôi cũng rất vui. Bạn đến từ đâu?'],['I’m from Hue. I live in Hanoi.','Tôi đến từ Huế. Tôi sống ở Hà Nội.'],['What do you do?','Bạn làm nghề gì?'],['Can you say that again, please?','Bạn nói lại giúp tôi được không?'],['What do you do?','Bạn làm nghề gì?'],['I’m a teacher. I study English.','Tôi là giáo viên. Tôi học tiếng Anh.']],
    39:[['A coffee, please.','Cho tôi một cà phê.'],['Anything else?','Bạn cần gì nữa không?'],['A cup of tea, please.','Cho tôi thêm một tách trà.'],['Here you are.','Của bạn đây.'],['Thank you.','Cảm ơn bạn.'],['You’re welcome.','Không có gì.']]
  };
  const projects=[
    ['Tên và chữ','Nghe hai chữ bất kỳ trong mỗi nhóm A–F/G–L/M–R/S–Z rồi viết lại. Đánh vần MAI và tên tự chọn.', ['Người nghe viết lại đúng thứ tự.','Nếu nhầm, chỉ rõ cặp cần luyện; không suy ra đã biết toàn bảng từ hai chữ.']],
    ['Nghe cả từ','Đọc cat/pen, ship/sheep và cup. Đổi vai: nghe rồi viết từ, sau đó mở nghĩa.',['Không nhìn văn bản trước câu nghe.','Giữ âm giữa/cuối; nhờ người hướng dẫn nghe nếu chưa chắc.']],
    ['Góc học của tôi','Giới thiệu ba đồ vật với màu và một người thân bằng This is my... .',['Có đủ my/màu/vật đúng thứ tự.','Đổi thông tin của ít nhất hai ví dụ, không chỉ sao mẫu.']],
    ['Giới thiệu và hỏi lại','Nói tên, nghề/trạng thái và một người thân; hỏi một câu be, trả lời một câu có/không.',['Có be, a/an phù hợp.','Đổi you→I khi trả lời về mình.']],
    ['Một cuộc làm quen','Hai vai trao đổi tên, xuất thân, nơi sống, nghề; có một lần xin nhắc lại và đánh vần.',['Đúng trọng tâm từng câu hỏi.','Dùng lại được khi đổi tên, nơi và thứ tự câu hỏi.']],
    ['Một ngày của hai người','Viết/nói thói quen của I và he/she; có thời gian, phủ định và một câu Do/Does.',['Có s trong khẳng định he/she.','Dạng cơ bản sau does/doesn’t; không thêm be trước hành động.']],
    ['Tình huống kết thúc khóa','Giới thiệu mình, nói thói quen/giờ/sở thích; gọi món, hỏi vị trí và viết lời nhắn hẹn giờ.',['Người khác hiểu và phản hồi được ý chính.','Tự sửa theo checklist, ghi riêng phần cần giáo viên nghe/đọc.']]
  ];
  function materialize(packet){
    const base=F.lessons[packet.day-1];
    const variants=probe=>/(?:viết|dạng) gọn/i.test(probe.prompt)?probe.answers:F.acceptedVariants(probe,packet.day);
    const prepare=probe=>({...probe,answers:variants(probe),...(packet.day===37&&/^\d+:\d+$/.test(probe.answers[0])?{format:'clock'}:{})});
    const transfer=packet.pool.map((x,i)=>({...prepare(x),id:`f2-method1-l${packet.day}-x${i+1}`}));
    const transferForms=packet.day<=4?[transfer.map(q=>q.id)]:[0,2,4].map(i=>transfer.slice(i,i+2).map(q=>q.id));
    const groups=packet.day<=4?[[1,4],[(packet.pool.length/2)|1,packet.pool.length-4],[packet.pool.length-1,2]]:[[2,3],[4,5],[0,1]];
    const retention=groups.flatMap((indices,round)=>indices.map((i,n)=>{const probe=packet.pool[i%packet.pool.length];return {...prepare(probe),id:`f2-method1-l${packet.day}-r${round+1}-${n+1}`,delayDays:[1,3,7][round]};}));
    return {...base,method:packet,transfer,transferForms,retention,scenarios:S.scenes.filter(s=>s.day===packet.day),dialogue:conversations[packet.day]||base.dialogue};
  }
  function decorate(base){return base.map(l=>{const packet=packets.find(p=>p.day===l.day);return packet?materialize(packet):l;});}
  function validate(){const errors=[];for(const packet of packets){if(packet.pool.length<6||!packet.checks.length||!packet.model||!packet.reason)errors.push(`Thiếu bài ${packet.day}`);for(const probe of packet.pool)for(const ref of probe.refs){const m=/^(\d+):(.*)$/.exec(ref);if(!m||+m[1]>packet.day||!F.lessons[+m[1]-1]?.concepts.some(c=>c.id===m[2]))errors.push(`Nguồn bài ${packet.day}: ${ref}`);}}return errors;}
  const lessons=decorate(F.lessons);
  function evidence(s,now=Date.now()){
    const result={};
    for(const lesson of lessons){
      const runs=Object.values(s.checkups||{}).filter(r=>r.day===lesson.day);
      // Repeating an answer just revealed by support/error is practice. A different
      // authored form can qualify now; the same item needs a 24-hour break.
      const qualified=(run,questions,after=0)=>questions.every(q=>{const a=run.answers[q.id];return a?.correct&&!a.assisted&&a.at>=after&&a.at<=now&&!(s.repairs?.[q.id]||[]).some(at=>at<=a.at&&a.at-at<86400000);});
      const forms=lesson.transferForms.map(ids=>lesson.transfer.filter(q=>ids.includes(q.id)));
      const full=runs.flatMap(r=>forms.filter(questions=>qualified(r,questions)).map(questions=>Math.max(...questions.map(q=>r.answers[q.id].at))));
      const applicationAt=s.completed.includes(lesson.day)&&(s.passedAt[lesson.day]||0)<=now&&full.length?Math.max(s.passedAt[lesson.day]||0,Math.min(...full)):0;
      let preceding=applicationAt;
      const milestones=[1,3,7].map(delay=>{
        const due=applicationAt&&preceding?Math.max(applicationAt+delay*86400000,preceding+86400000):null,questions=lesson.retention.filter(q=>q.delayDays===delay);
        const valid=due===null?[]:runs.filter(r=>qualified(r,questions,due));
        const passedAt=valid.length?Math.min(...valid.map(r=>Math.max(...questions.map(q=>r.answers[q.id].at)))):null;
        preceding=passedAt;
        return {delay,due,ready:due!==null&&now>=due,passed:passedAt!==null,passedAt,elapsedDays:passedAt?Math.floor((passedAt-applicationAt)/86400000):null};
      });
      const covered=new Set(runs.flatMap(r=>Object.values(r.answers).filter(a=>a.correct&&!a.assisted).map(a=>a.question)));
      result[lesson.day]={applicationAt,applicationPassed:!!applicationAt,covered:lesson.transfer.filter(q=>covered.has(q.id)).length,total:lesson.transfer.length,milestones,independentWritingChecked:s.methodReflections?.[lesson.day]==='checked'};
    }
    return result;
  }
  return {edition,packets,lessons,decorate,validate,evidence,projects};
});
